import pytest


class BadInput(Exception):
    def __init__(self, text: str) -> None:
        self.text = text


def sum_parsed(xs: list[str]) -> int:
    """Parse each string in xs as an integer and return their sum.

    Raises BadInput carrying the first string that is not an integer.
    An empty list sums to 0.
    """
    total = 0
    for s in xs:
        try:
            total += int(s)
        except ValueError:
            raise BadInput(s) from None
    return total


def test_sum_basic() -> None:
    assert sum_parsed(["1", "2", "3"]) == 6


def test_sum_empty() -> None:
    assert sum_parsed([]) == 0


def test_sum_negative_and_signed() -> None:
    assert sum_parsed(["-5", "10", "-2"]) == 3


def test_sum_large_values() -> None:
    assert sum_parsed(["10000000000000000000", "1"]) == 10000000000000000001


def test_bad_input_carries_text() -> None:
    with pytest.raises(BadInput) as excinfo:
        sum_parsed(["1", "abc", "3"])
    assert excinfo.value.text == "abc"


def test_first_bad_string_is_reported() -> None:
    with pytest.raises(BadInput) as excinfo:
        sum_parsed(["1", "x", "y"])
    assert excinfo.value.text == "x"


def test_float_string_is_bad() -> None:
    with pytest.raises(BadInput) as excinfo:
        sum_parsed(["2", "1.5"])
    assert excinfo.value.text == "1.5"


def test_empty_string_is_bad() -> None:
    with pytest.raises(BadInput) as excinfo:
        sum_parsed(["4", ""])
    assert excinfo.value.text == ""


def test_single_bad_element() -> None:
    with pytest.raises(BadInput) as excinfo:
        sum_parsed(["nope"])
    assert excinfo.value.text == "nope"
